# V29.b — Defensive safety net: se per qualche misconfig di ingress il redirect
# OAuth di Google finisce sul backend anziché sul frontend, ripiega redirigendo
# alla pagina Expo Router che sa gestire code/state. Non impatta il flow normale.
# V29.ap — La route GET /auth/google/callback ora completa lo scambio del code
# LATO SERVER (invece di limitarsi a redirigere al frontend). Motivazione: su
# APK Android il chrome custom tab spesso "perde" il redirect a un URL scheme
# custom dopo il primo hop → il vecchio bridge redirect al frontend non
# raggiungeva mai l'app. Ora invece:
#  1. Google reindirizza qui con code+state
#  2. Chiamiamo internamente la logica di scambio (equivalente a POST
#     /google-drive/oauth/exchange) — best effort, se fallisce non è drammatico
#  3. Rispondiamo con una pagina HTML "Autorizzato ✓ Torna all'app"
#  4. L'app in foreground rileva via polling /google-drive/status che il token
#     è ora presente → aggancia la UI.
@app.get("/auth/google/callback")
async def _oauth_callback_bridge(request: Request):
    from fastapi.responses import HTMLResponse, RedirectResponse
    qp = request.query_params
    code = qp.get("code")
    state = qp.get("state")
    err = qp.get("error")
    # V50.z54 — Rileva se il caller è un browser desktop web (non mobile app):
    # in quel caso il deep-link `frontend://` non funziona; usiamo un redirect
    # HTTPS al frontend web configurato invece.
    _ua = (request.headers.get("user-agent") or "").lower()
    _is_web = not any(k in _ua for k in ("expo", "advisoros-app", "okhttp", "cfnetwork/", "darwin", "android;"))
    _web_ret = _GD_FRONTEND_URL or "https://advisoros.it/"

    async def _try_exchange_and_page(ok: bool, message: str, detail: str = "") -> HTMLResponse:
        # HTML minimalista, brand navy + arancione, self-close-friendly
        # V50.i — Auto deep-link all'app Expo (scheme "frontend") + pulsante
        # manuale "Apri app". Su mobile il redirect a `frontend://impostazioni`
        # apre l'app installata (se presente) e la porta alla schermata
        # Impostazioni; da lì il polling `/api/google-drive/status` aggancia
        # la UI. In-app browser (WebBrowser.openAuthSessionAsync) si chiude
        # automaticamente al deep-link. Fallback: window.close() dopo 4s.
        color = "#16A34A" if ok else "#DC2626"
        icon = "✓" if ok else "✗"
        # V50.z54 — Web: redirect a URL HTTPS del frontend web (con query
        # ?oauth=google&status=ok/err) invece di deep-link mobile che non
        # funziona sui browser desktop.
        if _is_web:
            _sep = "&" if "?" in _web_ret else "?"
            deep_link = f"{_web_ret}{_sep}oauth=google&status=" + ("ok" if ok else "err")
        else:
            # V50.z110 — Deep-link direttamente alla schermata Google Drive
            # dell'app (scheme "frontend"): lì lo stato viene ricaricato e
            # l'utente vede subito "Collegato". Il custom tab Android si chiude
            # perché l'app usa lo stesso deep-link come returnUrl.
            deep_link = "frontend://google-drive?oauth=google&status=" + ("ok" if ok else "err")
        html = f"""<!DOCTYPE html><html lang="it"><head><meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>AdvisorOS · Google Drive</title>
<style>
body {{ font-family: -apple-system, Segoe UI, Roboto, sans-serif; margin: 0; padding: 32px;
       background: #0F2438; color: #FFF; min-height: 100vh; display: flex; flex-direction: column;
       align-items: center; justify-content: center; text-align: center; }}
.circle {{ width: 88px; height: 88px; border-radius: 44px; background: {color};
           display: flex; align-items: center; justify-content: center; font-size: 48px;
           color: #FFF; font-weight: 800; margin-bottom: 20px; }}
h1 {{ font-size: 22px; margin: 0 0 8px 0; font-weight: 800; letter-spacing: -0.4px; }}
p {{ color: rgba(255,255,255,0.75); font-size: 14px; margin: 4px 0; max-width: 380px; }}
.btn {{ display: inline-block; margin-top: 22px; padding: 14px 28px;
        background: #EA580C; color: #FFF; font-weight: 800; font-size: 15px;
        border-radius: 999px; text-decoration: none; letter-spacing: 0.3px;
        box-shadow: 0 6px 20px rgba(234,88,12,0.35); }}
.btn:active {{ transform: scale(0.98); }}
.hint {{ margin-top: 14px; color: #38BDF8; font-size: 11px; font-weight: 700;
        text-transform: uppercase; letter-spacing: 1px; }}
</style></head><body>
<div class="circle">{icon}</div>
<h1>{message}</h1>
<p>{detail}</p>
<a class="btn" href="{deep_link}">Apri AdvisorOS</a>
<p class="hint">Ti riportiamo automaticamente all'app…</p>
<script>
// 1) Tentativo di deep-link automatico (mobile): apre l'app se installata
setTimeout(function(){{
  try {{ window.location.href = "{deep_link}"; }} catch(e){{}}
}}, 600);
// 2) Fallback: chiude il tab/browser dopo 4s (utile su in-app WebBrowser)
setTimeout(function(){{ try{{ window.close(); }} catch(e){{}} }}, 4000);
</script>
</body></html>"""
        return HTMLResponse(content=html, status_code=200)

    if err:
        return await _try_exchange_and_page(False, "Autorizzazione annullata", err)
    if not code or not state:
        # V50.z110 — Su APK Android il custom tab può ricaricare/precaricare la
        # callback SENZA query (preload di Chrome, back, "Apri app" tardivo)
        # DOPO che il primo hit ha già completato lo scambio. Se esiste una
        # connessione salvata negli ultimi 5 minuti la mostriamo come riuscita
        # invece di un falso errore; altrimenti spieghiamo cosa fare.
        try:
            recent = await db.google_drive_connections.find_one(
                {"updated_at": {"$gte": utcnow() - timedelta(minutes=5)}},
                sort=[("updated_at", -1)],
            )
        except Exception:
            recent = None
        if recent:
            return await _try_exchange_and_page(True, "Google Drive già collegato",
                                                f"Account: {recent.get('google_email') or ''}")
        return await _try_exchange_and_page(False, "Callback OAuth incompleto",
                                            "Google non ha restituito il codice di autorizzazione. "
                                            "Torna all'app e riprova da Google Drive → Collega.")

    # Scambio server-side (stesso codice del POST /google-drive/oauth/exchange)
    try:
        if not _gd_configured():
            return await _try_exchange_and_page(False, "Google Drive non configurato",
                                                "Contatta l'amministratore del server")
        s = await db.google_oauth_states.find_one_and_delete({"_id": state})
        if not s:
            # V50.z54 — La callback può essere invocata DUE VOLTE (browser
            # preload di Chrome, back-button, refresh accidentale). Al primo
            # hit consumiamo lo state e salviamo la connessione. Al secondo
            # hit lo state non c'è più: se però l'utente è già collegato
            # (updated_at negli ultimi 5 minuti), NON dobbiamo mostrare
            # "sessione scaduta" perché la connessione È andata a buon fine.
            recent = await db.google_drive_connections.find_one(
                {"updated_at": {"$gte": utcnow() - timedelta(minutes=5)}},
                sort=[("updated_at", -1)],
            )
            if recent:
                return await _try_exchange_and_page(True, "Google Drive già collegato",
                                                    f"Account: {recent.get('google_email') or ''}")
            return await _try_exchange_and_page(False, "Sessione scaduta",
                                                "Riprova dalla schermata Google Drive")
        from google_auth_oauthlib.flow import Flow  # type: ignore
        from googleapiclient.discovery import build  # type: ignore
        # V29.aw — Use the redirect_uri and code_verifier persisted at start time
        # so the PKCE proof stays valid across the two requests.
        stored_redirect = s.get("redirect_uri") or _sanitize_redirect_uri(_GD_REDIRECT_URI)
        stored_verifier = s.get("code_verifier")
        flow = Flow.from_client_config(_gd_client_config(), scopes=_GD_SCOPES, state=state, redirect_uri=stored_redirect)
        if stored_verifier:
            flow.code_verifier = stored_verifier
        flow.fetch_token(code=code)
        creds = flow.credentials
        refresh = creds.refresh_token
        if not refresh:
            old = await db.google_drive_connections.find_one({"user_id": s["user_id"]})
            if old:
                refresh = _gd_fernet.decrypt(old["refresh_token_enc"].encode()).decode()
            else:
                return await _try_exchange_and_page(False, "Refresh token mancante",
                                                    "Revoca l'accesso in Google e riprova")
        google_email = None
        try:
            oauth2_service = build("oauth2", "v2", credentials=creds, cache_discovery=False)
            info = oauth2_service.userinfo().get().execute()
            google_email = info.get("email")
        except Exception:
            pass
        doc = {
            "user_id": s["user_id"],
            "refresh_token_enc": _gd_fernet.encrypt(refresh.encode()).decode(),
            "scopes": list(creds.scopes or _GD_SCOPES),
            "google_email": google_email,
            "updated_at": utcnow(),
        }
        await db.google_drive_connections.update_one(
            {"user_id": s["user_id"]}, {"$set": doc, "$setOnInsert": {"created_at": utcnow()}}, upsert=True
        )
        return await _try_exchange_and_page(True, "Google Drive collegato",
                                            f"Account: {google_email}" if google_email else "")
    except Exception as e:
        return await _try_exchange_and_page(False, "Errore durante il collegamento", str(e))


# =========================
# Helpers
# =========================
def utcnow() -> datetime:
    return datetime.now(timezone.utc)


# V50.f — Callback server-side per Dropbox (specular a quello Google in
# `/auth/google/callback`). Dropbox reindirizza qui con ?code=...&state=...
# perché l'ingress Emergent instrada `/auth/*` al backend, NON al frontend.
# Prima esisteva solo la pagina Expo Router a `/auth/dropbox/callback.tsx`
# che però NON veniva mai raggiunta → 404 "Not Found" restituito da FastAPI.
# Ora facciamo lo scambio del code lato server e mostriamo una pagina HTML
# di successo; il polling `/api/dropbox/status` nell'app aggancia la UI.
@app.get("/auth/dropbox/callback")
async def _dropbox_oauth_callback_bridge(request: Request):
    from fastapi.responses import HTMLResponse
    qp = request.query_params
    code = qp.get("code")
    state = qp.get("state")
    err = qp.get("error") or qp.get("error_description")

    def _page(ok: bool, message: str, detail: str = "") -> HTMLResponse:
        # V50.i — Auto deep-link "frontend://dropbox" + pulsante manuale.
        color = "#0061FF" if ok else "#DC2626"
        icon = "✓" if ok else "✗"
        deep_link = "frontend://dropbox?oauth=dropbox&status=" + ("ok" if ok else "err")
        html = f"""<!DOCTYPE html><html lang="it"><head><meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>AdvisorOS · Dropbox</title>
<style>
body {{ font-family: -apple-system, Segoe UI, Roboto, sans-serif; margin: 0; padding: 32px;
       background: #0F2438; color: #FFF; min-height: 100vh; display: flex; flex-direction: column;
       align-items: center; justify-content: center; text-align: center; }}
.circle {{ width: 88px; height: 88px; border-radius: 44px; background: {color};
           display: flex; align-items: center; justify-content: center; font-size: 48px;
           color: #FFF; font-weight: 800; margin-bottom: 20px; }}
h1 {{ font-size: 22px; margin: 0 0 8px 0; font-weight: 800; letter-spacing: -0.4px; }}
p {{ color: rgba(255,255,255,0.75); font-size: 14px; margin: 4px 0; max-width: 380px; }}
.btn {{ display: inline-block; margin-top: 22px; padding: 14px 28px;
        background: #EA580C; color: #FFF; font-weight: 800; font-size: 15px;
        border-radius: 999px; text-decoration: none; letter-spacing: 0.3px;
        box-shadow: 0 6px 20px rgba(234,88,12,0.35); }}
.btn:active {{ transform: scale(0.98); }}
.hint {{ margin-top: 14px; color: #38BDF8; font-size: 11px; font-weight: 700;
        text-transform: uppercase; letter-spacing: 1px; }}
</style></head><body>
<div class="circle">{icon}</div>
<h1>{message}</h1>
<p>{detail}</p>
<a class="btn" href="{deep_link}">Apri AdvisorOS</a>
<p class="hint">Ti riportiamo automaticamente all'app…</p>
<script>
setTimeout(function(){{
  try {{ window.location.href = "{deep_link}"; }} catch(e){{}}
}}, 600);
setTimeout(function(){{ try{{ window.close(); }} catch(e){{}} }}, 4000);
</script>
</body></html>"""
        return HTMLResponse(content=html, status_code=200)

    if err:
        return _page(False, "Autorizzazione annullata", err)
    if not code or not state:
        return _page(False, "Callback OAuth incompleto", "Manca code o state")

    try:
        if not _dbx_configured():
            return _page(False, "Dropbox non configurato",
                         "Contatta l'amministratore del server")
        st = await db.dropbox_oauth_states.find_one_and_delete({"_id": state})
        if not st:
            return _page(False, "Sessione scaduta",
                         "Riprova dalla schermata Dropbox")
        # V50.q — Mongo può restituire datetime tz-naive: normalizza a UTC
        # prima del confronto per evitare "can't compare offset-naive and
        # offset-aware datetimes".
        exp = st.get("expires_at")
        if exp is not None and getattr(exp, "tzinfo", None) is None:
            exp = exp.replace(tzinfo=timezone.utc)
        if exp is not None and exp < utcnow():
            return _page(False, "Stato OAuth scaduto",
                         "Riprova dalla schermata Dropbox")
        # Scambia il code con Dropbox usando lo stesso client_secret + code_verifier
        async with httpx.AsyncClient(timeout=20) as client:
            r = await client.post(
                "https://api.dropboxapi.com/oauth2/token",
                data={
                    "code": code,
                    "grant_type": "authorization_code",
                    "client_id": _DBX_APP_KEY,
                    "client_secret": _DBX_APP_SECRET,
                    "redirect_uri": _DBX_REDIRECT_URI,
                    "code_verifier": st.get("code_verifier", ""),
                },
            )
        if r.status_code != 200:
            logger.warning("[dropbox-callback] token exchange %s: %s", r.status_code, r.text[:200])
            return _page(False, "Scambio token fallito", f"HTTP {r.status_code}")
        tok = r.json()
        # Best-effort account info
        dropbox_email = None
        account_id = tok.get("account_id")
        try:
            if tok.get("access_token"):
                async with httpx.AsyncClient(timeout=10) as c2:
                    ar = await c2.post(
                        "https://api.dropboxapi.com/2/users/get_current_account",
                        headers={"Authorization": f"Bearer {tok['access_token']}"},
                    )
                    if ar.status_code == 200:
                        aj = ar.json()
                        dropbox_email = (aj.get("email") or "").lower() or None
                        account_id = aj.get("account_id") or account_id
        except Exception:
            pass
        await db.dropbox_connections.update_one(
            {"user_id": st["user_id"]},
            {"$set": {
                "user_id": st["user_id"],
                "account_id": account_id,
                "dropbox_email": dropbox_email,
                "refresh_token": tok.get("refresh_token", ""),
                "scopes": tok.get("scope") or _DBX_SCOPES,
                "updated_at": utcnow(),
            }},
            upsert=True,
        )
        return _page(True, "Dropbox collegato",
                     f"Account: {dropbox_email}" if dropbox_email else "")
    except Exception as e:
        logger.warning("[dropbox-callback] exception: %s", e)
        return _page(False, "Errore durante il collegamento", str(e))


def hash_password(pw: str) -> str:
    return bcrypt.hashpw(pw.encode(), bcrypt.gensalt()).decode()


def verify_password(pw: str, hashed: str) -> bool:
    try:
        return bcrypt.checkpw(pw.encode(), hashed.encode())
    except Exception:
        return False


def create_jwt(user_id: str) -> str:
    payload = {
        "sub": user_id,
        "iat": int(utcnow().timestamp()),
        "exp": int((utcnow() + timedelta(days=JWT_EXP_DAYS)).timestamp()),
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALG)


def create_temp_2fa_token(user_id: str) -> str:
    payload = {
        "sub": user_id,
        "purpose": "2fa_pending",
        "iat": int(utcnow().timestamp()),
        "exp": int((utcnow() + timedelta(minutes=TEMP_2FA_TOKEN_MINUTES)).timestamp()),
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALG)


def totp_provisioning_uri(email: str, secret: str) -> str:
    return pyotp.TOTP(secret).provisioning_uri(name=email, issuer_name=TOTP_ISSUER)


def qr_png_data_url(data: str) -> str:
    qr = qrcode.QRCode(error_correction=qrcode.constants.ERROR_CORRECT_M, box_size=6, border=2)
    qr.add_data(data)
    qr.make(fit=True)
    img = qr.make_image(fill_color="#0F2438", back_color="white")
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode()


def generate_backup_codes(count: int = 10) -> list[str]:
    # 10-char, split into 5-5 for display: XXXXX-XXXXX
    codes = []
    for _ in range(count):
        raw = secrets.token_hex(5).upper()  # 10 chars
        codes.append(f"{raw[:5]}-{raw[5:]}")
    return codes


def hash_backup_code(code: str) -> str:
    # Normalize by removing dashes/spaces + upper
    norm = code.replace("-", "").replace(" ", "").upper()
    return bcrypt.hashpw(norm.encode(), bcrypt.gensalt()).decode()


def verify_backup_code(code: str, hashed: str) -> bool:
    try:
        norm = code.replace("-", "").replace(" ", "").upper()
        return bcrypt.checkpw(norm.encode(), hashed.encode())
    except Exception:
        return False


def strip_id(doc: Optional[dict]) -> Optional[dict]:
    if not doc:
        return doc
    doc.pop("_id", None)
    return doc


async def get_current_user(authorization: Optional[str] = Header(None)) -> dict:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Not authenticated")
    token = authorization.split(" ", 1)[1].strip()

    # Try JWT first
    user_id = None
    try:
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALG])
        user_id = payload.get("sub")
    except Exception:
        # Try session token (Google auth)
        session = await db.user_sessions.find_one({"session_token": token}, {"_id": 0})
        if session:
            exp = session.get("expires_at")
            if isinstance(exp, datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=timezone.utc)
                if exp < utcnow():
                    raise HTTPException(status_code=401, detail="Session expired")
            user_id = session.get("user_id")

    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")

    user = await db.users.find_one({"user_id": user_id}, {"_id": 0, "password_hash": 0, "totp_secret": 0, "totp_secret_pending": 0, "backup_codes": 0})
    if not user:
        raise HTTPException(status_code=401, detail="User not found")
    return user


