# V50.l — RAG semantico con embeddings OpenAI text-embedding-3-small.
# Migliora drasticamente il retrieve quando l'utente scrive con parole
# diverse rispetto al contenuto dei documenti (sinonimi, forme flesse,
# rimescolamento). Embeddings sono cachati nel chunk (`embedding` field)
# così il costo di embed è pagato UNA VOLTA per chunk (all'ingestion o al
# primo retrieve). Query embedding è calcolato al volo (~50ms).
_EMBEDDING_MODEL = "text-embedding-3-small"
_EMBEDDING_DIM = 1536  # dimensione output text-embedding-3-small
_EMBEDDING_URL = "https://integrations.emergentagent.com/llm/openai/v1/embeddings"


async def _axon_embed(text: str) -> Optional[List[float]]:
    """Ritorna il vettore embedding di `text` via OpenAI proxy Emergent.
    Best-effort: se il proxy fallisce o la chiave manca, ritorna None e il
    caller cadrà nel fallback Jaccard."""
    text = (text or "").strip()
    if not text:
        return None
    key = os.getenv("EMERGENT_LLM_KEY", "")
    if not key:
        return None
    try:
        async with httpx.AsyncClient(timeout=8.0) as c:
            r = await c.post(
                _EMBEDDING_URL,
                headers={"Authorization": f"Bearer {key}"},
                json={"model": _EMBEDDING_MODEL, "input": text[:8000]},
            )
        if r.status_code != 200:
            return None
        data = r.json().get("data") or []
        if not data:
            return None
        emb = data[0].get("embedding")
        if not emb or len(emb) != _EMBEDDING_DIM:
            return None
        return emb
    except Exception as exc:
        logger.debug("[axon-embed] failed: %s", exc)
        return None


def _cosine_sim(a: List[float], b: List[float]) -> float:
    """Similitudine coseno tra due vettori (assunti pre-normalizzati o meno)."""
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = 0.0
    na = 0.0
    nb = 0.0
    for x, y in zip(a, b):
        dot += x * y
        na += x * x
        nb += y * y
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na ** 0.5 * nb ** 0.5)


async def _retrieve_master_doc_chunks(
    tenant: str,
    query: str,
    top_k: int = RAG_TOP_K,
    min_sim: float = RAG_MIN_SIMILARITY,
) -> List[dict]:
    """Retrieve top-K most relevant chunks for a query, scoped to a tenant.
    V50.l — Uso embeddings semantici come primary + Jaccard come fallback.
    Se `embedding` non è ancora presente sul chunk, viene calcolato una
    tantum e persistito (lazy compute) durante il primo retrieve rilevante.
    """
    _, q_tokens = _normalize_and_tokenize(query)
    if not q_tokens:
        return []

    # STEP 1: Prefiltro Jaccard classico (pre-scoring veloce su indice tokens)
    cursor = db.master_doc_chunks.find(
        {"tenant_id": tenant, "tokens": {"$in": q_tokens}},
        {"_id": 0, "chunk_id": 1, "doc_id": 1, "content": 1, "tokens": 1,
         "page_number": 1, "embedding": 1},
    ).limit(500)  # safety cap on candidates
    prelim: List[dict] = []
    async for c in cursor:
        jsim = _jaccard(q_tokens, c.get("tokens") or [])
        c["_jscore"] = jsim
        prelim.append(c)

    if not prelim:
        return []

    # STEP 2: Query embedding (async, best-effort)
    q_emb = await _axon_embed(query)

    # STEP 3: Se ho l'embedding query, riordino i top candidati per cosine sim.
    # Per limitare il costo, calcolo embeddings dei chunk mancanti solo sui
    # top-40 per jaccard (non su tutti i 500). Lazy compute + persist.
    if q_emb:
        prelim.sort(key=lambda x: x.get("_jscore", 0.0), reverse=True)
        candidates = prelim[:40]
        # Chunk senza embedding → embed in parallelo e persist
        missing = [c for c in candidates if not c.get("embedding")]
        if missing:
            async def _embed_and_save(chunk: dict) -> None:
                emb = await _axon_embed(chunk.get("content") or "")
                if emb:
                    chunk["embedding"] = emb
                    try:
                        await db.master_doc_chunks.update_one(
                            {"chunk_id": chunk["chunk_id"]},
                            {"$set": {"embedding": emb}},
                        )
                    except Exception:
                        pass
            await asyncio.gather(*[_embed_and_save(c) for c in missing[:12]])

        # Cosine sim vs query embedding
        for c in candidates:
            emb = c.get("embedding")
            if emb:
                c["_score"] = _cosine_sim(q_emb, emb)
            else:
                # Chunk senza embedding (skippato per limite budget) → usa jaccard scalato
                c["_score"] = max(0.0, c.get("_jscore", 0.0) * 0.5)
        # Soglia semantica più permissiva (0.35 su cosine ≈ semanticamente rilevante)
        scored = [c for c in candidates if c.get("_score", 0.0) >= 0.35]
        scored.sort(key=lambda x: x.get("_score", 0.0), reverse=True)
        top = scored[:top_k]
    else:
        # Fallback: pura Jaccard con soglia originale
        scored = [c for c in prelim if c.get("_jscore", 0.0) >= min_sim]
        for c in scored:
            c["_score"] = c.get("_jscore", 0.0)
        scored.sort(key=lambda x: x.get("_score", 0.0), reverse=True)
        top = scored[:top_k]

    if not top:
        return []

    # Cleanup + enrich con doc name
    for c in top:
        c.pop("embedding", None)
        c.pop("_jscore", None)
    doc_ids = list({c["doc_id"] for c in top})
    doc_map: Dict[str, str] = {}
    docs_cursor = db.master_documents.find(
        {"doc_id": {"$in": doc_ids}, "tenant_id": tenant},
        {"_id": 0, "doc_id": 1, "name": 1},
    )
    async for d in docs_cursor:
        doc_map[d["doc_id"]] = d.get("name") or ""
    for c in top:
        c["doc_name"] = doc_map.get(c["doc_id"], "?")
    return top


# =========================================================================
# V29.ag — Axon Quick Actions con cache server-side + auto-refresh.
#
# Flow:
#  1) Il client (chat AxonOS) invoca POST /api/axon/quick-action con {label, prompt}
#  2) Server cerca in db.axon_qa_cache un doc (user_id, label). Se `updated_at`
#     è entro `QA_CACHE_TTL_DAYS` giorni → risposta istantanea dalla cache.
#  3) Se cache mancante o stale → chiama internamente `assistant_chat` con un
#     prompt arricchito che istruisce l'LLM a recuperare autonomamente i dati
#     dalle fonti già configurate nelle regole (URL, file allegati). L'LLM
#     esistente già ha accesso a web search + file delle regole → nessuna
#     richiesta esplicita di upload lato utente.
#  4) La risposta viene persistita in cache con timestamp, poi restituita
#     al client con `from_cache=false` e `updated_at`.
# =========================================================================

QA_CACHE_TTL_DAYS = 7


class AxonQuickActionIn(BaseModel):
    label: str
    prompt: str
    force_refresh: bool = False


@api_router.post("/axon/quick-action")
async def axon_quick_action(body: AxonQuickActionIn, user=Depends(get_current_user)):
    label = (body.label or "").strip()
    prompt = (body.prompt or "").strip()
    if not label or not prompt:
        raise HTTPException(status_code=400, detail="label e prompt richiesti")

    now = utcnow()
    key = {"user_id": user["user_id"], "label": label}

    # 1) Cache lookup
    if not body.force_refresh:
        cached = await db.axon_qa_cache.find_one(key, {"_id": 0})
        if cached:
            updated = cached.get("updated_at")
            try:
                if isinstance(updated, str):
                    updated_dt = datetime.fromisoformat(updated.replace("Z", "+00:00"))
                elif isinstance(updated, datetime):
                    updated_dt = updated
                else:
                    updated_dt = None
            except Exception:
                updated_dt = None
            if updated_dt:
                # normalizza tz-aware
                if updated_dt.tzinfo is None:
                    updated_dt = updated_dt.replace(tzinfo=timezone.utc)
                age_days = (now - updated_dt).total_seconds() / 86400.0
                if age_days < QA_CACHE_TTL_DAYS and cached.get("reply"):
                    return {
                        "reply": cached["reply"],
                        "updated_at": updated_dt.isoformat(),
                        "from_cache": True,
                        "cache_age_days": round(age_days, 2),
                    }

    # 2) Cache stale/missing → richiesta all'LLM con istruzioni di auto-refresh.
    enriched_prompt = (
        f"{prompt}\n\n"
        "ISTRUZIONI OPERATIVE:\n"
        "- Usa i file e link presenti nelle 'regole' come fonte primaria.\n"
        "- Se il dato richiesto non è aggiornato nelle regole, cerca autonomamente "
        "online (web_search) SOLO nelle fonti/link già indicati nelle regole "
        "o in fonti ufficiali equivalenti (es. GME per PUN, ARERA per bollette).\n"
        "- Non chiedere mai all'utente di caricare file: recupera tutto da solo.\n"
        "- Formatta la risposta in modo chiaro (tabelle Markdown se utile) e "
        "specifica sempre la fonte/data del dato."
    )

    chat_body = AssistantChatIn(message=enriched_prompt, session_id=None, attachments=[])
    try:
        result = await assistant_chat(chat_body, user)  # type: ignore[arg-type]
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Auto-refresh Axon fallito: {e}")

    reply = (result or {}).get("reply", "") if isinstance(result, dict) else ""
    if not reply:
        raise HTTPException(status_code=500, detail="Risposta vuota dall'assistente")

    # 3) Persist in cache
    await db.axon_qa_cache.update_one(
        key,
        {
            "$set": {
                **key,
                "reply": reply,
                "updated_at": now,
                "web_sources": (result.get("web_sources") if isinstance(result, dict) else []) or [],
                "used_web_search": bool(result.get("used_web_search")) if isinstance(result, dict) else False,
            }
        },
        upsert=True,
    )

    return {
        "reply": reply,
        "updated_at": now.isoformat(),
        "from_cache": False,
        "cache_age_days": 0.0,
    }


@api_router.get("/assistant/history")
async def assistant_history(session_id: Optional[str] = None, user=Depends(get_current_user)):
    """Load conversation history. If session_id not given, returns latest session."""
    if not session_id:
        # Find latest session
        latest = await db.assistant_messages.find_one(
            {"user_id": user["user_id"]},
            {"session_id": 1},
            sort=[("created_at", -1)],
        )
        if not latest:
            return {"session_id": None, "messages": [], "assistant_name": await _get_assistant_name(user)}
        session_id = latest["session_id"]

    cursor = db.assistant_messages.find(
        {"user_id": user["user_id"], "session_id": session_id},
        {"_id": 0, "role": 1, "content": 1, "created_at": 1},
    ).sort("created_at", 1).limit(100)
    msgs = [m async for m in cursor]
    return {
        "session_id": session_id,
        "messages": msgs,
        "assistant_name": await _get_assistant_name(user),
    }


@api_router.post("/assistant/reset")
async def assistant_reset(user=Depends(get_current_user)):
    """Start a new conversation. Old sessions remain in DB but a new session_id is issued."""
    session_id = f"asst_{user['user_id']}_{uuid.uuid4().hex[:10]}"
    return {"session_id": session_id, "assistant_name": await _get_assistant_name(user)}


